<script setup>import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{api}from'../api.js';import PublicPageShell from'../components/PublicPageShell.vue';const route=useRoute(),event=ref(null);const active=computed(()=>event.value&&Date.now()>=new Date(event.value.starts_at)&&Date.now()<=new Date(event.value.ends_at));onMounted(async()=>event.value=await api(`/public/events/${route.params.slug}`));</script><template><PublicPageShell v-slot="{site}"><main v-if="event" class="page-main"><div class="container"><span v-if="active" class="live">● LIVE SEKARANG</span><h1 class="section-title">{{event.title}}</h1><p class="section-lead">{{event.location}} · {{new Date(event.starts_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}} WIB</p><img v-if="event.image_url" :src="event.image_url" class="event-cover"><article class="content-prose mt-4" v-html="event.content"></article><a v-if="event.reservation_enabled" :href="`https://wa.me/${site.settings.whatsapp_number}?text=${encodeURIComponent('Halo, saya ingin reservasi event '+event.title)}`" target="_blank" class="btn btn-success rounded-pill mt-4">{{event.reservation_label||'Reservasi Kehadiran'}}</a></div></main></PublicPageShell></template><style scoped>.live{color:#16a34a;font-weight:900}.event-cover{max-width:100%;border-radius:16px;max-height:500px;object-fit:cover}</style>
